<?php
use Illuminate\Support\Facades\Route;use App\Http\Controllers\AuthController;use App\Http\Controllers\ProductionController;
Route::get('/',fn()=>redirect('/dashboard'));
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'show'])->name('login');Route::post('/login',[AuthController::class,'login']);});
Route::middleware('auth')->group(function(){Route::post('/logout',[AuthController::class,'logout'])->name('logout');Route::get('/dashboard',[ProductionController::class,'dashboard'])->name('dashboard');Route::post('/production/sync-backlog',[ProductionController::class,'syncBacklog'])->name('production.sync-backlog');Route::get('/production',[ProductionController::class,'verification'])->name('production');Route::post('/production/{item}/verify',[ProductionController::class,'verify'])->name('verify');Route::get('/ready-for-print',[ProductionController::class,'queue'])->name('queue');Route::post('/batches',[ProductionController::class,'batch'])->name('batch.create');Route::get('/batches',[ProductionController::class,'batches'])->name('batches');Route::get('/batches/{batch}',[ProductionController::class,'showBatch'])->name('batch.show');Route::post('/batches/{batch}/edge-print',[ProductionController::class,'requestEdgePrint'])->name('batch.edge-print');Route::post('/batches/{batch}/printed',[ProductionController::class,'markPrinted'])->name('batch.printed');});
